const byEnglish = new Map(translationPairs.map((pair) => [pair.en, pair]));
const byGerman = new Map<string, TranslationPair>();

for (const pair of translationPairs) {
  const existing = byGerman.get(pair.de);
  if (!existing || pair.en !== pair.de) byGerman.set(pair.de, pair);
}

function preserveWhitespace(source: string, translated: string): string {
  const leading = source.match(/^\s*/u)?.[0] ?? "";
  const trailing = source.match(/\s*$/u)?.[0] ?? "";
  return `${leading}${translated}${trailing}`;
}

export function translateCustomerText(value: string, locale: AppLocale): string {
  const trimmed = value.trim();
  if (!trimmed) return value;

  const pair = locale === "en"
    ? byGerman.get(trimmed) ?? byEnglish.get(trimmed)
    : byEnglish.get(trimmed) ?? byGerman.get(trimmed);
  if (pair) return preserveWhitespace(value, pair[locale]);

  const cartMatch = trimmed.match(/^Open (?:cart|bag), (\d+) items?$/u);
  if (cartMatch) {
    const count = Number(cartMatch[1]);
    const translated = locale === "de"
      ? `Warenkorb öffnen, ${count} ${count === 1 ? "Artikel" : "Artikel"}`
      : `Open cart, ${count} ${count === 1 ? "item" : "items"}`;
    return preserveWhitespace(value, translated);
  }

  const itemCountMatch = trimmed.match(/^(\d+) items?$/u);
  if (itemCountMatch) {
    const count = Number(itemCountMatch[1]);
    return preserveWhitespace(
      value,
      locale === "de" ? `${count} Artikel` : `${count} ${count === 1 ? "item" : "items"}`,
    );
  }

  const copyrightMatch = trimmed.match(/^(©\s+\d{4}\s+ra&ra\.)\s+(?:All rights reserved\.|Alle Rechte vorbehalten\.)$/iu);
  if (copyrightMatch) {
    return preserveWhitespace(
      value,
      `${copyrightMatch[1]} ${locale === "de" ? "Alle Rechte vorbehalten." : "All rights reserved."}`,
    );
  }

  return value;
}
